#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    int to, next, time, cost;
} Edge;

typedef struct {
    int node, cost;
    long long time;
} HeapItem;

static HeapItem *heap;
static int heap_size, heap_capacity;

void push(HeapItem item) {
    if (heap_size == heap_capacity) {
        heap_capacity = heap_capacity ? heap_capacity * 2 : 1024;
        heap = realloc(heap, (size_t)heap_capacity * sizeof(HeapItem));
    }

    int i = heap_size++;
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap[parent].time <= item.time) break;
        heap[i] = heap[parent];
        i = parent;
    }
    heap[i] = item;
}

HeapItem pop(void) {
    HeapItem result = heap[0];
    HeapItem last = heap[--heap_size];

    if (heap_size > 0) {
        int i = 0;
        while (2 * i + 1 < heap_size) {
            int child = 2 * i + 1;
            if (child + 1 < heap_size &&
                heap[child + 1].time < heap[child].time) {
                child++;
            }
            if (heap[child].time >= last.time) break;
            heap[i] = heap[child];
            i = child;
        }
        heap[i] = last;
    }

    return result;
}

int main(void) {
    int budget, n, m;
    if (scanf("%d %d %d", &budget, &n, &m) != 3) return 0;

    int *head = malloc((size_t)(n + 1) * sizeof(int));
    for (int i = 1; i <= n; i++) head[i] = -1;

    Edge *edges = malloc((size_t)(2 * m) * sizeof(Edge));
    int edge_count = 0;

    for (int i = 0; i < m; i++) {
        int a, b, t, p;
        scanf("%d %d %d %d", &a, &b, &t, &p);

        edges[edge_count] = (Edge){b, head[a], t, p};
        head[a] = edge_count++;

        edges[edge_count] = (Edge){a, head[b], t, p};
        head[b] = edge_count++;
    }

    int start, destination;
    scanf("%d %d", &start, &destination);

    int width = budget + 1;
    size_t state_count = (size_t)(n + 1) * width;
    long long *dist = malloc(state_count * sizeof(long long));
    for (size_t i = 0; i < state_count; i++) dist[i] = LLONG_MAX;

    size_t start_index = (size_t)start * width;
    dist[start_index] = 0;
    push((HeapItem){start, 0, 0});

    while (heap_size > 0) {
        HeapItem current = pop();
        size_t index = (size_t)current.node * width + current.cost;

        if (current.time != dist[index]) continue;
        if (current.node == destination) {
            printf("%lld\n", current.time);
            free(head);
            free(edges);
            free(dist);
            free(heap);
            return 0;
        }

        for (int e = head[current.node]; e != -1; e = edges[e].next) {
            int new_cost = current.cost + edges[e].cost;
            if (new_cost > budget) continue;

            long long new_time = current.time + edges[e].time;
            size_t next_index = (size_t)edges[e].to * width + new_cost;

            if (new_time < dist[next_index]) {
                dist[next_index] = new_time;
                push((HeapItem){edges[e].to, new_cost, new_time});
            }
        }
    }

    printf("-1\n");

    free(head);
    free(edges);
    free(dist);
    free(heap);
    return 0;
}
